// User verbatim: "digerlerini yap"
// localStorage key: "tripandtick:locale", value Locale union.
// UR = RTL (LOCALE_DIR.ur = "rtl"), digerleri LTR.

export type Locale =
  | "tr"
  | "en"
  | "de"
  | "fr"
  | "es"
  | "nl"
  | "zh"
  | "hi"
  | "ur"
  | "pt"
  | "pt-BR"
  | "ja"
  | "ko"
  | "it"
  | "ru"
  | "uk"
  | "az";

export const DEFAULT_LOCALE: Locale = "tr";
export const SUPPORTED_LOCALES: Locale[] = [
  "tr",
  "en",
  "de",
  "fr",
  "es",
  "nl",
  "zh",
  "hi",
  "ur",
  "pt",
  "pt-BR",
  "ja",
  "ko",
  "it",
  "ru",
  "uk",
  "az",
];

