// Yeni diller (pt/pt-BR/ja/ko/it/ru/uk/az): senkron sozluk = EN alias (Worker-safe).
// Gercek ceviri public/i18n/dict.<locale>.json'dan client-side fetch edilir (I18nProvider)
// — Cloudflare 3 MiB Worker limiti icin bundle disinda tutulur.
export const DICTIONARIES = {
  ...BASE_DICTIONARIES,
  pt: BASE_DICTIONARIES.en,
  "pt-BR": BASE_DICTIONARIES.en,
  ja: BASE_DICTIONARIES.en,
  ko: BASE_DICTIONARIES.en,
  it: BASE_DICTIONARIES.en,
  ru: BASE_DICTIONARIES.en,
  uk: BASE_DICTIONARIES.en,
  az: BASE_DICTIONARIES.en,
};

export type Dictionary = typeof DICTIONARIES.tr;

export const LOCALE_STORAGE_KEY = "tripandtick:locale";

export function isLocale(value: unknown): value is Locale {
  return (
    value === "tr" ||
    value === "en" ||
    value === "de" ||
    value === "fr" ||
    value === "es" ||
    value === "nl" ||
    value === "zh" ||
    value === "hi" ||
    value === "ur" ||
    value === "pt" ||
    value === "pt-BR" ||
    value === "ja" ||
    value === "ko" ||
    value === "it" ||
    value === "ru" ||
    value === "uk" ||
    value === "az"
  );
}
